def _detect_gpu_count() -> int:
    # vLLM requires torch; keep this import local so the script can still be
    # imported without immediately touching CUDA.
    try:
        import torch
    except Exception:
        return 0
    try:
        return int(torch.cuda.device_count())
    except Exception:
        return 0


def _parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description=(
            "Reproducibility + tensor parallel demo for vLLM. "
            "Use --mode optimized for maximum NVIDIA GPU throughput."
        ))
    parser.add_argument("--model",
                        type=str,
                        default="Qwen/Qwen3-30B-A3B",
                        help="HuggingFace model name or local path.")
    parser.add_argument(
        "--tensor-parallel-size",
        "--tp",
        type=int,
        default=0,
        help=("Tensor parallel size. 0 means auto-detect "
              "(uses all visible GPUs)."),
    )
    parser.add_argument(
        "--mode",
        choices=["reproducible", "optimized"],
        default="reproducible",
        help=(
            "reproducible: deterministic-ish scheduling (slower). "
            "optimized: best throughput on NVIDIA GPUs (non-deterministic)."),
    )
    parser.add_argument(
        "--dtype",
        choices=["auto", "float16", "bfloat16", "float32"],
        default="auto",
        help=(
            "Model dtype. For NVIDIA Ampere/Hopper, bfloat16 is often best. "
            "Use auto to follow the model config (float32 will be downcast)."),
    )
    parser.add_argument(
        "--profile-dir",
        "--torch-profiler-dir",
        type=str,
        default="",
        help=(
            "If set, enable vLLM Torch Profiler and save traces under this "
            "directory (viewable in Perfetto at https://ui.perfetto.dev/). "
            "Profiling adds significant overhead; keep the run small."),
    )
    return parser.parse_args()


def _configure_env(mode: str) -> None:
    # NOTE: vLLM reads some config from env. For reproducibility, we set these
    # explicitly. For optimized throughput, we avoid forcing reproducibility
    # knobs (and we *enable* multiprocessing scheduling).
    if mode == "reproducible":
        # Turn off multiprocessing to make scheduling deterministic, and enable
        # batch invariance to reduce scheduling-related variation.
        os.environ["VLLM_ENABLE_V1_MULTIPROCESSING"] = "0"
        os.environ["VLLM_BATCH_INVARIANT"] = "1"
    else:
        # Best throughput: allow multiprocessing scheduling.
        os.environ["VLLM_ENABLE_V1_MULTIPROCESSING"] = "1"
        # If the user had this set globally, it can reduce throughput; override
        # it explicitly here for clarity.
        os.environ["VLLM_BATCH_INVARIANT"] = "0"


def main():
    args = _parse_args()
    _configure_env(args.mode)

    # Import after env config so vLLM can pick up env-based settings.
    from vllm import LLM, SamplingParams

    tp = args.tensor_parallel_size
    if tp <= 0:
        tp = _detect_gpu_count() or 1

    # Sampling params are part of the reproducibility story, but they don't
    # materially affect tensor-parallel configuration.
    sampling_params = SamplingParams(temperature=0.8, top_p=0.95)

    llm = LLM(
        model=args.model,
        tensor_parallel_size=tp,
        dtype=args.dtype,
        gpu_memory_utilization=0.9,
        # enable_expert_parallel=True,
        trust_remote_code=True,
        profiler_config=({
            "profiler": "torch",
            "torch_profiler_dir": args.profile_dir,
        } if args.profile_dir else None),
    )

    if args.profile_dir:
        llm.start_profile()

    outputs = llm.generate(prompts, sampling_params)

    if args.profile_dir:
        llm.stop_profile()
        # Give background worker processes time to flush trace files to disk.
        import time

        time.sleep(10)
        print(f"Profiler traces saved under: {args.profile_dir!r}")
    print("-" * 50)
    total_input_tokens = 0
    total_generated_tokens = 0
    for output in outputs:
        prompt = output.prompt
        input_tokens = (len(output.prompt_token_ids)
                        if output.prompt_token_ids is not None else 0)
        total_input_tokens += input_tokens

        print(f"Prompt: {prompt!r}")
        print(f"Input tokens: {input_tokens}")

        # One request can have multiple outputs (e.g. n>1).
        for completion in output.outputs:
            gen_tokens = len(completion.token_ids)
            total_generated_tokens += gen_tokens
            print(
                f"Output[{completion.index}] tokens: {gen_tokens}\n"
                f"Generated text: {completion.text!r}"
            )
        print("-" * 50)

    print(
        f"Total input tokens: {total_input_tokens}\n"
        f"Total generated tokens: {total_generated_tokens}"
    )

    # Try generating random numbers outside vLLM
    # The same number is output across runs, meaning that the random state
    # in the user code has been updated by vLLM
    print(random.randint(0, 100))


if __name__ == "__main__":
    main()
